const $ = id => document.getElementById(id);
const state = { branch: "all", type: "all", era: "all", query: "", selected: null };
const eras = ["all","1600s","1700s","1800s","1900s","2000s"];
const el = (tag, className, value) => { const node = document.createElement(tag); if (className) node.className = className; if (value != null) node.textContent = value; return node; };
function link(label, href) { const a = el("a", "", label + " ↗"); a.href = href; if (/^https?:/.test(href)) { a.target = "_blank"; a.rel = "noopener noreferrer"; } return a; }
function visible() {
  return EVENTS.filter(e => (state.branch === "all" || e.branch === state.branch)
    && (state.type === "all" || e.type === state.type)
    && (state.era === "all" || Math.floor(e.year / 100) * 100 === Number(state.era.slice(0,4)))
    && (!state.query || [e.title,e.summary,e.detail,e.place,...e.people,BRANCHES[e.branch].label].join(" ").toLowerCase().includes(state.query)))
    .sort((a,b) => a.year - b.year || a.title.localeCompare(b.title));
}
function renderEras() {
  const host = $("eras"); host.replaceChildren();
  eras.forEach(era => {
    const count = era === "all" ? EVENTS.length : EVENTS.filter(e => Math.floor(e.year / 100) * 100 === Number(era.slice(0,4))).length;
    const b = el("button", state.era === era ? "active" : "", era === "all" ? "All years" : era);
    b.type = "button"; b.setAttribute("aria-pressed", String(state.era === era));
    b.append(el("small", "", String(count)));
    b.addEventListener("click", () => { state.era = era; render(); }); host.append(b);
  });
}
function renderList(rows) {
  const host = $("event-list"); host.replaceChildren(); $("empty").hidden = rows.length > 0;
  rows.forEach(e => {
    const button = el("button", "event" + (e.id === state.selected ? " selected" : ""));
    button.type = "button"; button.style.setProperty("--branch", BRANCHES[e.branch].color);
    button.setAttribute("aria-label", e.date + ": " + e.title + ". Open details.");
    button.setAttribute("aria-pressed", String(e.id === state.selected));
    const top = el("span", "event-top"); top.append(el("span", "event-year", e.date), el("span", "event-branch", BRANCHES[e.branch].label));
    const tags = el("span", "event-tags"); tags.append(el("span", "tag", e.type), el("span", "tag evidence-" + e.evidence, e.evidence === "family" ? "Family account" : e.evidence[0].toUpperCase() + e.evidence.slice(1)));
    if (MEDIA[e.id]) tags.append(el("span", "tag", "View image"));
    button.append(top, el("span", "event-title", e.title), el("span", "event-summary", e.summary), tags);
    button.addEventListener("click", () => { state.selected = e.id; location.hash = e.id; render(); if (matchMedia("(max-width:850px)").matches) $("detail").scrollIntoView({behavior:"smooth",block:"start"}); });
    host.append(button);
  });
}
function renderDetail(e) {
  const host = $("detail"); host.replaceChildren(); if (!e) { host.append(el("p", "detail-body", "Choose another filter to see an event.")); return; }
  host.style.setProperty("--branch", BRANCHES[e.branch].color);
  const top = el("div", "detail-top"); top.append(el("p", "eyebrow", BRANCHES[e.branch].label + " · " + e.type), el("h2", "", e.title), el("span", "when", e.date));
  const body = el("div", "detail-body"); body.append(el("p", "", e.detail));
  if (MEDIA[e.id]) {
    const [path, alt, caption] = MEDIA[e.id];
    const figure = el("figure", "event-media");
    const imageLink = el("a"); imageLink.href = ROOT + path;
    const image = el("img"); image.src = ROOT + path; image.alt = alt; image.loading = "lazy";
    imageLink.append(image); figure.append(imageLink, el("figcaption", "", caption)); body.append(figure);
  }
  const facts = el("div", "fact-grid");
  [["Place",e.place],["Evidence",e.evidence === "family" ? "Family account" : e.evidence[0].toUpperCase()+e.evidence.slice(1)]].forEach(([name,value]) => { const f = el("div","fact"); f.append(el("b","",name),el("span","",value)); facts.append(f); });
  body.append(facts,el("p","caveat",e.caveat),el("h3","","People in this story"));
  const names = el("ul"); e.people.forEach(name => names.append(el("li","",name))); body.append(names,el("h3","","Read the evidence"));
  const sources = el("ul"); e.sources.forEach(([label,url]) => { const li = el("li"); li.append(link(label,url)); sources.append(li); }); body.append(sources);
  const actions = el("div","detail-links"); actions.append(link("Read the full story",ROOT+e.story)); body.append(actions); host.append(top,body);
}
function render() {
  renderEras(); const rows = visible();
  if (!rows.some(e => e.id === state.selected)) state.selected = rows[0]?.id || null;
  $("showing-count").textContent = rows.length + " of " + EVENTS.length + " events";
  $("filter-note").textContent = rows.length ? "Showing " + rows.length + " events from " + rows[0].year + " to " + rows[rows.length-1].year + ". Select any card to open its records." : "No events match the current filters.";
  renderList(rows); renderDetail(rows.find(e => e.id === state.selected));
}
$("total-count").textContent = EVENTS.length + " curated events";
Object.entries(BRANCHES).forEach(([key,value]) => { const option = el("option","",value.label); option.value = key; $("branch").append(option); });
TYPES.forEach(type => { const option = el("option","",type); option.value = type; $("type").append(option); });
$("search").addEventListener("input", event => { state.query = event.target.value.trim().toLowerCase(); render(); });
$("branch").addEventListener("change", event => { state.branch = event.target.value; render(); });
$("type").addEventListener("change", event => { state.type = event.target.value; render(); });
$("reset").addEventListener("click", () => { state.branch="all";state.type="all";state.era="all";state.query="";$("search").value="";$("branch").value="all";$("type").value="all";render(); });
window.addEventListener("hashchange", () => { const id = decodeURIComponent(location.hash.slice(1)); if (id === state.selected) return; if (EVENTS.some(e => e.id === id)) { state.branch="all";state.type="all";state.era="all";state.query="";$("search").value="";$("branch").value="all";$("type").value="all";state.selected=id;render(); } });
const initialId = decodeURIComponent(location.hash.slice(1)); state.selected = EVENTS.some(e => e.id === initialId) ? initialId : "kings-mountain";
render();
